/**
 * Typer — character-by-character reveal. Fires once when scrolled into view.
 * `frame` advances on an interval; each char's class is derived from global
 * progress minus its own bezier control point, so the wave ripples across.
 */
function Typer({ text, as: Tag = "span", fps = 20, cycles = 3, cycleLength = 0.5, delay = 0, threshold = 0.35, once = false, style, className }) {
  const ref = useRef(null);
  const [frame, setFrame] = useState(-1); // -1 = untouched (initial)
  const variations = useRef(ALL_VARIATIONS.slice().sort(() => 0.5 - Math.random()));

  const { words, frames, denominator } = useMemo(() => {
    const letters = text.replace(/\s/g, "").length;
    const divisor = letters > 1 ? letters - 1 : 1;
    const f = letters ? fps * (1 + letters * 0.01) : 0;
    const den = f - f * cycleLength || 1;
    const parts = text.split(/(\s+)/);
    let i = 0;
    const w = parts.map((part, wi) => {
      if (part.trim() === "") return { space: true, text: part, key: `s${wi}` };
      const chars = part.split("").map((ch, ci) => {
        const cp = roundToStep(bezierEase(i / divisor, 0, 0.75, 0.75, 0), 0.05);
        i += 1;
        return { ch, cp, key: `c${wi}-${ci}` };
      });
      return { space: false, chars, key: `w${wi}` };
    });
    return { words: w, frames: f, denominator: den };
  }, [text, fps, cycleLength]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { setFrame(frames); return; }

    let timer = null, iv = null;
    const stop = () => {
      if (timer) { clearTimeout(timer); timer = null; }
      if (iv) { clearInterval(iv); iv = null; }
    };
    const run = () => {
      stop();
      // reshuffle so the ripple never looks the same twice
      variations.current = ALL_VARIATIONS.slice().sort(() => 0.5 - Math.random());
      timer = setTimeout(() => {
        setFrame(0);
        iv = setInterval(() => {
          setFrame((f) => {
            if (f >= frames) { clearInterval(iv); iv = null; return f; }
            return f + 1;
          });
        }, 1000 / fps);
      }, delay * 1000);
    };

    const io = new IntersectionObserver((entries) => {
      const e = entries[entries.length - 1];
      if (e.isIntersecting) {
        if (once) io.disconnect();
        run();
      } else if (!once) {
        // left the viewport: reset so it types in again on the way back
        stop();
        setFrame(-1);
      }
    }, { threshold });
    io.observe(el);

    return () => { io.disconnect(); stop(); };
  }, [frames, fps, delay, threshold, once]);

  const started = frame >= 0;
  const progress = started ? frame / denominator : 0;

  const classFor = (cp) => {
    if (!started) return "char charInit";
    let p = clamp(roundToStep(progress - cp, 0.1), 0, 1);
    if (p <= 0) return "char charInit";
    if (p >= 1) return "char";
    const idx = Math.round(remap(p, 0, 1, 0, cycles));
    return `char ${variations.current[idx % variations.current.length]}`;
  };

  return (
    <Tag ref={ref} data-typer="" data-typer-type={started ? (frame >= frames ? "done" : "in") : "initial"} className={className} style={style}>
      {words.map((w) =>
        w.space ? w.text : (
          <span className="word" key={w.key}>
            {w.chars.map((c) => (
              <span key={c.key} className={classFor(c.cp)}>{c.ch}</span>
            ))}
          </span>
        )
      )}
    </Tag>
  );
}

/* ====================== GHOST REVEAL (about) ====================== */

function axisFor(dir, scale) {
  const pct = `${scale}%`;
  switch (dir) {
    case "up":
      return { image: "linear-gradient(to bottom, transparent 0%, transparent 40%, rgba(0,0,0,0.55) 58%, #000 74%, #000 100%)", size: `100% ${pct}`, from: "50% 0%", to: "50% 100%" };
    case "down":
      return { image: "linear-gradient(to bottom, #000 0%, #000 26%, rgba(0,0,0,0.55) 42%, transparent 60%, transparent 100%)", size: `100% ${pct}`, from: "50% 100%", to: "50% 0%" };
    case "left":
      return { image: "linear-gradient(to right, #000 0%, #000 26%, rgba(0,0,0,0.55) 42%, transparent 60%, transparent 100%)", size: `${pct} 100%`, from: "100% 50%", to: "0% 50%" };
    case "right":
      return { image: "linear-gradient(to right, transparent 0%, transparent 40%, rgba(0,0,0,0.55) 58%, #000 74%, #000 100%)", size: `${pct} 100%`, from: "0% 50%", to: "100% 50%" };
    default:
      return axisFor("up", scale);
  }
}

function GhostReveal({ play, direction = "up", scale = 700, duration = 1100, easing = "cubic-bezier(0.16, 1, 0.3, 1)", reduce = false, children, style }) {
  const a = axisFor(direction, scale);
  const maskStyle = reduce
    ? { opacity: play ? 1 : 0, transition: `opacity 700ms ${easing}` }
    : {
        WebkitMaskImage: a.image, maskImage: a.image,
        WebkitMaskSize: a.size, maskSize: a.size,
        WebkitMaskRepeat: "no-repeat", maskRepeat: "no-repeat",
        WebkitMaskPosition: play ? a.to : a.from, maskPosition: play ? a.to : a.from,
        transition: `-webkit-mask-position ${duration}ms ${easing}, mask-position ${duration}ms ${easing}`,
      };
  return <div style={{ ...maskStyle, ...style }}>{children}</div>;
}

function Tile({ src }) {
  return (
    <div style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden", background: PAPER }}>
      {/* light, airy, faintly warm — desaturated rather than washed in colour */}
      <img
        src={src}
        alt=""
        style={{
          width: "100%", height: "100%", objectFit: "cover", display: "block",
          filter: "grayscale(0.55) saturate(0.85) contrast(0.85) brightness(1.2)",
        }}
      />
      {/* the faintest rose wash — a faded photograph, not a duotone */}
      <div style={{ position: "absolute", inset: 0, background: PINK, mixBlendMode: "multiply", opacity: 0.06 }} />
      <div style={{ position: "absolute", inset: 0, background: BLUSH, mixBlendMode: "screen", opacity: 0.2 }} />
      <div style={{ position: "absolute", inset: 0, backgroundImage: "radial-gradient(rgba(120,60,90,0.2) 0.9px, transparent 1.1px)", backgroundSize: "3.5px 3.5px", mixBlendMode: "multiply", opacity: 0.04, pointerEvents: "none" }} />
    </div>
  );
}

