/* ============================ ABOUT =========================== */

function About() {
  const wrapRef = useRef(null);
  const [progress, setProgress] = useState(0);
  const [reduce, setReduce] = useState(false);
  // Below tablet width there is no room for a side-by-side column, so the photos
  // move underneath the text instead of overlapping it.
  const { isPhone } = useViewport();
  const [narrow, setNarrow] = useState(false);

  useEffect(() => {
    setReduce(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = wrapRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const scrollable = rect.height - window.innerHeight;
      const p = scrollable > 0 ? -rect.top / scrollable : 0;
      setProgress(Math.max(0, Math.min(1, p)));
    };
    const onResize = () => {
      setNarrow(window.innerWidth < 1024);
      onScroll();
    };
    onResize();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
    };
  }, []);

  // 24 photos is too many for one pass at any size: each gets too little time and
  // the tail of the scroll runs empty. Take an evenly-spread subset instead, so
  // the selection still ranges across all of them rather than favouring a block.
  const shown = useMemo(() => {
    const target = isPhone ? 10 : narrow ? 12 : 14;
    const step = IMAGES.length / target;
    const picked = [];
    for (let k = 0; k < target; k++) {
      const idx = Math.min(IMAGES.length - 1, Math.round(k * step));
      if (!picked.includes(idx)) picked.push(idx);
    }
    return picked;
  }, [isPhone, narrow]);

  // Timing is measured against the visible set, not the full array.
  const windowFor = (slot) => {
    const start = IMG_START + (slot / Math.max(1, shown.length - 1)) * IMG_SPAN;
    return { start, end: Math.min(start + WLEN, CLEAR_BY) };
  };

  const linePlay = progress > LINE_AT;

  // The scattered coordinates were authored against the full viewport, so their
  // raw range is narrow. Normalise them and stretch across the whole stage, and
  // size the tiles as a PERCENTAGE of the stage so they always fill it.
  // Placing by the original viewport coordinates left dead zones, because those
  // values clustered. Instead deal every photo a cell in a loose grid that spans
  // the whole stage, then jitter it so it still reads as scattered, not gridded.
  const cols = isPhone ? 2 : narrow ? 3 : 3;
  const jitter = (n) => {
    const v = Math.sin(n * 127.1 + 311.7) * 43758.5453;
    return (v - Math.floor(v)) * 2 - 1; // -1..1, deterministic
  };

  const stage = (
    <div style={{ position: "relative", width: "100%", height: "100%" }}>
      {shown.map((imgIndex, slot) => {
        const im = IMAGES[imgIndex];
        const { start, end } = windowFor(slot);
        const play = progress > start && progress < end;
        const portrait = im.ratio > 1;
        const wPct = portrait ? (narrow ? (isPhone ? 40 : 30) : 44) : (narrow ? (isPhone ? 56 : 42) : 60);
        const rows = Math.ceil(shown.length / cols);
        const col = slot % cols;
        const row = Math.floor(slot / cols);
        const lx = cols > 1 ? col / (cols - 1) : 0.5;
        const ly = rows > 1 ? row / (rows - 1) : 0.5;
        const left = Math.max(0, Math.min(100 - wPct, lx * (100 - wPct) + jitter(imgIndex) * 7));
        const top = Math.max(0, Math.min(76, ly * 76 + jitter(imgIndex + 99) * 5));
        return (
          <GhostReveal
            key={imgIndex}
            play={play}
            direction={im.dir}
            duration={DURATIONS[imgIndex]}
            reduce={reduce}
            style={{
              position: "absolute",
              left: `${left}%`,
              top: `${top}%`,
              width: `${wPct}%`,
              aspectRatio: `1 / ${im.ratio}`,
              zIndex: im.z,
            }}
          >
            <Tile src={im.src} />
          </GhostReveal>
        );
      })}
    </div>
  );

  const copy = (
    <div style={{ maxWidth: narrow ? 560 : 440, width: "100%", textAlign: "left", flexShrink: 0 }}>
      <Typer
        text="about me"
        as="h2"
        fps={20}
        style={{ display: "block", fontFamily: DISPLAY, fontSize: narrow ? "clamp(30px, 6.4vw, 52px)" : "clamp(34px, 7vw, 86px)", fontWeight: 600, lineHeight: 1.02, letterSpacing: "-0.02em", color: INK, margin: narrow ? "0 0 14px" : "0 0 26px" }}
      />
      <p style={{ fontFamily: BODY, fontWeight: 300, fontSize: "clamp(15px, 1.8vw, 18px)", lineHeight: 1.75, color: INK, margin: 0, textAlign: "left" }}>
        I make things for screens and for people, always chasing the
        next thing to learn, and none of it comes from nowhere. Every
        idea I have is borrowed from a person, a place, or a moment I
        couldn't quite let go of.
      </p>
      <div style={{ margin: narrow ? "16px 0 0" : "30px 0 0", minHeight: narrow ? 44 : 62, textAlign: "left" }}>
        <GhostReveal play={linePlay} direction="up" scale={700} duration={1500} reduce={reduce}>
          <p style={{ fontFamily: BODY, fontSize: "clamp(15px, 1.8vw, 18px)", lineHeight: 1.75, fontWeight: 400, color: PINK, margin: 0 }}>
            I am nothing but an amalgamation of all the people I have met
            and the places I have been.
          </p>
        </GhostReveal>
      </div>
    </div>
  );

  return (
    <section id="about" ref={wrapRef} style={{ height: isPhone ? "420vh" : narrow ? "500vh" : "620vh", position: "relative" }}>
      <div style={{ position: "sticky", top: 0, height: "100vh", overflow: "hidden", background: PAPER }}>
        {narrow ? (
          // Phone / iPad: no room for a side column, so go back to the original
          // idea — the photos scatter across the WHOLE frame and pass over the
          // text, which stays pinned underneath them.
          <>
            <div style={{ position: "absolute", inset: 0, zIndex: 2 }}>{stage}</div>
            <div
              style={{
                position: "absolute",
                inset: 0,
                zIndex: 1,
                display: "flex",
                alignItems: "center",
                padding: isPhone ? "80px 22px 40px" : "96px 40px 48px",
                boxSizing: "border-box",
                pointerEvents: "none",
              }}
            >
              {copy}
            </div>
          </>
        ) : (
          // Desktop: text left, photos confined to their own column on the right.
          <div
            style={{
              height: "100%",
              width: "100%",
              boxSizing: "border-box",
              display: "flex",
              overflow: "hidden",
              justifyContent: "center",
              flexDirection: "row",
              alignItems: "center",
              gap: "clamp(28px, 4vw, 56px)",
              paddingLeft: "max(clamp(24px, 6vw, 72px), calc((100vw - 1080px) / 2 + clamp(24px, 6vw, 72px)))",
              paddingRight: "clamp(24px, 4vw, 48px)",
            }}
          >
            {copy}
            <div style={{ position: "relative", minWidth: 0, flex: 1.35, minHeight: 0, height: "92vh", alignSelf: "stretch" }}>
              {stage}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

